var root=UnityEngine.GameObject.Find("01_AssembledFacade_SharedBoundaryPosts");var temp=new UnityEngine.GameObject("Temporary_FacadeSeamProbe");var colliders=new System.Collections.Generic.List<UnityEngine.MeshCollider>();int samples=0;var misses=new System.Collections.Generic.List<string>();
try{
foreach(var mf in root.GetComponentsInChildren<UnityEngine.MeshFilter>()){if(!mf.GetComponent<UnityEngine.Renderer>().enabled)continue;var go=new UnityEngine.GameObject(mf.name);go.transform.SetParent(temp.transform);go.transform.SetPositionAndRotation(mf.transform.position,mf.transform.rotation);go.transform.localScale=mf.transform.lossyScale;var mc=go.AddComponent<UnityEngine.MeshCollider>();mc.sharedMesh=mf.sharedMesh;colliders.Add(mc);}UnityEngine.Physics.SyncTransforms();
bool Hit(UnityEngine.Ray ray){foreach(var c in colliders)if(c.Raycast(ray,out var h,2))return true;return false;}
foreach(float x in new[]{-3f,-2.913f,-2.907f,-.093f,-.087f,0f,.087f,.093f,2.857f,2.863f,3f})foreach(float y in new[]{.219f,.221f,1.5f,3.019f,3.021f,3.239f,3.241f,3.459f,3.461f,4.7f,6.259f,6.261f}){samples++;if(!Hit(new UnityEngine.Ray(new UnityEngine.Vector3(x,y,1),UnityEngine.Vector3.back)))misses.Add($"Front {x},{y}");}
foreach(float z in new[]{-.14f,-.28f,-1.5f,-2.907f,-2.913f,-3f})foreach(float y in new[]{.23f,1.5f,3.23f,3.25f,4.7f,6.27f}){samples++;if(!Hit(new UnityEngine.Ray(new UnityEngine.Vector3(4,y,z),UnityEngine.Vector3.left)))misses.Add($"Side {z},{y}");}
var report=new{samples,misses,scope="Sampled timber/plaster boundaries and stack interfaces from exterior; excludes intended window opening and open top edges. Temporary test colliders removed."};System.IO.File.WriteAllText("ArtSource/Blender/Architecture/CrookedMortar/FacadeBay01/SeamValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));if(misses.Count>0)throw new System.Exception("Seam probe misses "+string.Join(";",misses));return report;
}finally{UnityEngine.Object.DestroyImmediate(temp);}
